from concurrent.futures import ThreadPoolExecutor

import pytest


def parity(x: int) -> int:
    return x % 2


def parities(xs: list[int], *, workers: int = 4) -> list[int]:
    """Return parity(x) for each x in xs, computed on a thread pool.

    Results are returned in input order, and the output must be identical
    for any positive value of ``workers``. Raises ValueError if workers < 1.
    """
    if workers < 1:
        raise ValueError("workers must be >= 1")
    with ThreadPoolExecutor(max_workers=workers) as ex:
        return list(ex.map(parity, xs))


def test_parities_basic() -> None:
    assert parities([0, 1, 2, 3]) == [0, 1, 0, 1]


def test_parities_negative() -> None:
    assert parities([-1, -2, -3]) == [1, 0, 1]


def test_parities_empty() -> None:
    assert parities([]) == []


def test_parities_preserves_order() -> None:
    xs = list(range(1000))
    assert parities(xs) == [x % 2 for x in xs]


@pytest.mark.parametrize("workers", [1, 2, 3, 8, 64])
def test_parities_independent_of_worker_count(workers: int) -> None:
    xs = [7, -4, 10, 0, 13, 22, -9] * 50
    assert parities(xs, workers=workers) == [parity(x) for x in xs]


def test_parities_rejects_zero_workers() -> None:
    with pytest.raises(ValueError):
        parities([1, 2], workers=0)


def test_parities_uses_thread_pool(monkeypatch: pytest.MonkeyPatch) -> None:
    created: list[int] = []

    class Spy(ThreadPoolExecutor):
        def __init__(self, max_workers: int | None = None, **kwargs: object) -> None:
            created.append(max_workers or 0)
            super().__init__(max_workers=max_workers)

    monkeypatch.setattr("concurrent.futures.ThreadPoolExecutor", Spy)
    monkeypatch.setattr(__name__ + ".ThreadPoolExecutor", Spy, raising=False)
    parities([1, 2, 3], workers=3)
    assert created == [3]
